export class List {
  constructor(read) {
    this.read = read;
    this.account = null;
    this.items = [];
    this.cache = new Map();
    this.epoch = 0;
    this.pending = null;
  }

  switchAccount(account) {
    this.account = account;
    this.epoch++;
    this.pending = null;
    this.items = this.cache.get(account) ?? [];
  }

  async refresh() {
    if (this.pending) return this.pending;

    const account = this.account;
    const epoch = this.epoch;
    let result;
    try {
      result = this.read(account);
    } catch (error) {
      result = Promise.reject(error);
    }
    const request = Promise.resolve(result).then(items => {
      if (this.epoch === epoch) {
        this.items = items;
        this.cache.set(account, items);
      }
    }).finally(() => {
      if (this.pending === request) this.pending = null;
    });
    this.pending = request;
    return request;
  }
}
import assert from 'node:assert/strict';
import { List } from './list.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}

{
  const lateA = deferred();
  const list = new List(id => id === 'A' ? lateA.promise : Promise.resolve(['B-only']));
  list.switchAccount('A');
  const old = list.refresh();
  list.switchAccount('B');
  await list.refresh();
  lateA.resolve(['A-private']);
  await old;
  assert.deepEqual(list.items, ['B-only'], 'late A result leaked into B view');
  assert.deepEqual(list.cache.get('B'), ['B-only'], 'late A result poisoned B cache');
  assert.equal(list.cache.has('A'), false, 'obsolete A result entered shared cache');
}

{
  const first = deferred();
  const second = deferred();
  let reads = 0;
  const list = new List(() => (++reads === 1 ? first : second).promise);
  list.switchAccount('A');
  const one = list.refresh();
  const two = list.refresh();
  assert.equal(reads, 1, 'overlapping refreshes repeated the read');
  first.resolve(['first']);
  await Promise.all([one, two]);
  assert.deepEqual(list.items, ['first']);
  const three = list.refresh();
  assert.equal(reads, 2, 'settled refresh was reused instead of fetching again');
  second.resolve(['second']);
  await three;
  assert.deepEqual(list.items, ['second']);
}

{
  const lateA = deferred();
  const freshA = deferred();
  let reads = 0;
  const list = new List(() => (++reads === 1 ? lateA : freshA).promise);
  list.switchAccount('A');
  const old = list.refresh();
  list.switchAccount('B');
  list.switchAccount('A');
  const current = list.refresh();
  assert.equal(reads, 2, 'new account selection reused an obsolete request');
  lateA.resolve(['obsolete']);
  await old;
  assert.deepEqual(list.items, []);
  assert.equal(list.cache.has('A'), false);
  freshA.resolve(['current']);
  await current;
  assert.deepEqual(list.items, ['current']);
}

{
  let reads = 0;
  const list = new List(() => {
    reads++;
    if (reads === 1) throw new Error('offline');
    return ['recovered'];
  });
  list.switchAccount('A');
  await assert.rejects(list.refresh(), /offline/);
  await list.refresh();
  assert.equal(reads, 2, 'failed read was reused');
  assert.deepEqual(list.items, ['recovered']);
}

console.log('list refresh checks passed');

